// swift-tools-version: 6.2
import PackageDescription

/// BiathlonKit built for Android, with Java bindings generated by swift-java's jextract.
///
/// jextract's Swift thunks must be compiled into the module they extract, so this package
/// compiles BiathlonKit's own sources (Sources/BiathlonKit/Shared links to them), the
/// Android-only additions (Sources/BiathlonKit/Android) and the thunks
/// (Sources/BiathlonKit/Generated) as one module of the same name. jextract runs as
/// a command rather than as its SwiftPM plugin, which reads only the target's own directory
/// and does not follow the link.
let swiftSettings: [SwiftSetting] = [
    .enableUpcomingFeature("NonisolatedNonsendingByDefault"),
    .enableUpcomingFeature("InferIsolatedConformances"),
    .enableUpcomingFeature("ExistentialAny"),
]

let package = Package(
    name: "BiathlonKitAndroid",
    platforms: [.macOS(.v26)],
    products: [
        .library(name: "BiathlonKit", type: .dynamic, targets: ["BiathlonKit"])
    ],
    dependencies: [
        .package(url: "https://github.com/swiftlang/swift-java", .upToNextMinor(from: "0.7.0"))
    ],
    targets: [
        .target(
            name: "BiathlonKit",
            // Linked statically with the Swift runtime, so the app ships a single libBiathlonKit.so.
            dependencies: [.product(name: "SwiftJavaStatic", package: "swift-java")],
            // Trial finding (swift-java 0.7.0): the thunks of async functions start a Task that
            // captures JNI pointers, which Swift 6 rejects as a data race. Its own samples build
            // in Swift 5 mode; the iOS package still checks BiathlonKit in Swift 6.
            swiftSettings: swiftSettings + [
                .swiftLanguageMode(.v5),
                // Swift 6 mode's /regex/ literals, which BiathlonKit uses.
                .enableUpcomingFeature("BareSlashRegexLiterals"),
            ],
            // Trial finding (Swift SDK for Android 6.4.1): a static FoundationNetworking links
            // curl but not the OpenSSL and zlib that curl calls, so the library fails to load
            // ("cannot locate symbol X509_free"). OpenSSL ships in the SDK, zlib in Android.
            linkerSettings: [
                .linkedLibrary("ssl", .when(platforms: [.android])),
                .linkedLibrary("crypto", .when(platforms: [.android])),
                .linkedLibrary("z", .when(platforms: [.android])),
            ]
        )
    ]
)
